/**
 * Per-lesson metadata, generated by scripts/migrate-to-astro.mjs from the
 * original lesson files and scripts/badge_map.json (now in legacy/).
 *
 *   title      - display title for the dashboard ("Hello World & Compile")
 *   badgeClass - activity type CSS class (discovery | basic-app | expand-app | rpg | assessment | hybrid)
 *   badgeLabel - activity type label shown on the dashboard
 *   group      - the "Unit.Lesson" group number ("1.1")
 *   targets    - <3 clear learning targets for the lesson, each paired with a success criteria
 */
export interface LearningTarget {
  target: string;
  criteria: string;
}

export interface LessonMeta {
  title: string;
  badgeClass: string;
  badgeLabel: string;
  group: string;
  targets: LearningTarget[];
}

